/**
 * borradorFactura.js — Generador del BORRADOR DE FACTURA en PDF (vía impresión).
 *
 * PLANTILLA OBLIGATORIA ALSO CASALS (regla fijada por Maria): cabecera real
 * (logo + datos de empresa, imagen extraída del Word oficial), bloques azules
 * (BORRADOR FACTURA / FECHA BORRADOR / C.I.F CLIENTE / INFORMACIÓN CLIENTE),
 * tabla COD. ARTÍCULO/DESCRIPCIÓN/CANTIDAD/PRECIO/DTO/IMPORTE/IVA, forma de
 * pago CaixaBank (ES86 2100 3502 9222 0016 0922 · SWIFT CAIXESBBXXX) y cuadro
 * BASE IMPONIBLE / % / IVA / TOTAL, con el banner ferrosCA al pie.
 * EL FORMATO NO SE CAMBIA.
 *
 * Decisiones de Maria (13/07/2026):
 *   · Nº de borrador = "BORRADOR OT" + número de OT (ej. BORRADOR OT014663).
 *   · Cliente: SOLO el nombre (sin dirección). El C.I.F se rellena si viene en
 *     las líneas (Sell_to_Customer_No); si no, queda en blanco.
 *   · Vencimiento: SIEMPRE a 60 días de la fecha del borrador. Recibo al cobro.
 */

const LOGO_CABECERA = "data:image/png;base64,";
const BANNER_FERROSCA = "data:image/jpeg;base64,";

import { htmlBorradorFacturaFerros } from "./borradorFacturaFerros.js";

// Multiempresa (24/09/2026): FERROSCA tiene su propia plantilla oficial
// (borradorFacturaFerros.js). La de ALSO CASALS (esta) NO se ha tocado.
const empresaBorrador = () => {
  try { return JSON.parse(localStorage.getItem("agente_ventas_empresa_v1") || "null"); } catch { return null; }
};
const esFerros = (e = empresaBorrador()) => !!(e && !e.porDefecto && /ferros/i.test(`${e.nombre} ${e.displayName || ""}`));

const IVA_PCT = 21;

const eurN = (v) =>
  (Number(v) || 0).toLocaleString("es-ES", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const fechaLarga = (d) =>
  d.toLocaleDateString("es-ES", { day: "numeric", month: "long", year: "numeric" });

/** Abre una ventana con el borrador y lanza el diálogo de impresión (Guardar como PDF). */
export function generarBorradorFactura(params) {
  // Multiempresa (24/09/2026): la plantilla oficial es la de ALSO CASALS
  try {
    const e = JSON.parse(localStorage.getItem("agente_ventas_empresa_v1") || "null");
    if (e && e.id && !e.porDefecto && !esFerros(e) && !window.confirm(`Atención: estás en ${e.displayName || e.nombre}, pero la plantilla del borrador es la de ALSO CASALS (logo, CIF y banco de Also). ¿Generarlo igualmente?`)) return false;
  } catch {}
  const html = htmlBorradorFactura(params);
  const w = window.open("", "_blank");
  if (!w) return false;
  w.document.write(html);
  w.document.close();
  return true;
}

/** Devuelve el HTML del borrador (MISMA plantilla oficial, sin cambios).
 *  Lo usan el botón «Borrador PDF» (ventana + imprimir) y la generación
 *  en lote desde el chat del Explorador de OTs (PDF directo en el backend). */
export function htmlBorradorFactura(params) {
  if (esFerros()) return htmlBorradorFacturaFerros(params); // plantilla oficial de FERROSCA
  const { numeroOT, cliente, cifCliente, filas } = params;
  const num = (numeroOT || "").toString().padStart(6, "0");
  const hoy = new Date();
  const vto = new Date(hoy.getTime() + 60 * 24 * 60 * 60 * 1000); // +60 días
  const base = filas.reduce((a, l) => a + (Number(l.importe) || 0), 0);
  const iva = base * IVA_PCT / 100;
  const total = base + iva;

  const filaHtml = (l) => {
    const esTexto = !l.numero && !(Number(l.importe) || 0) && !(Number(l.cantidad) || 0);
    if (esTexto) {
      return `<tr>
        <td></td>
        <td>${escapa(l.descripcion)}</td>
        <td class="num"></td><td class="num"></td><td class="num">0</td><td class="num"></td><td class="num"></td>
      </tr>`;
    }
    return `<tr>
      <td>${escapa(l.numero)}</td>
      <td>${escapa(l.descripcion)}</td>
      <td class="num">${String(l.cantidad).replace(".", ",")}</td>
      <td class="num">${eurN(l.precio)}</td>
      <td class="num">${l.dtoPct ? String(l.dtoPct).replace(".", ",") : "0"}</td>
      <td class="num">${eurN(l.importe)}</td>
      <td class="num">${IVA_PCT}</td>
    </tr>`;
  };

  const html = `<!DOCTYPE html>
<html lang="es"><head><meta charset="utf-8"><title>Borrador OT${num}</title>
<style>
  @page { size: A4; margin: 10mm 12mm; }
  * { box-sizing: border-box; -webkit-print-color-adjust: exact; print-color-adjust: exact; color-adjust: exact; }
  body { font-family: Arial, Helvetica, sans-serif; color: #1f2937; font-size: 10.5px; margin: 0; }
  .cabecera img { width: 100%; display: block; }
  .bloques { display: flex; gap: 14px; margin-top: 12px; }
  .col-izq { width: 200px; flex-shrink: 0; }
  .col-fecha { width: 170px; flex-shrink: 0; }
  .col-cli { flex: 1; }
  .titulo-azul { background: #1f5fa8; color: #fff; font-weight: 700; text-align: center; padding: 4px 6px; font-size: 10px; }
  .caja { background: #f2f2f2; padding: 4px 8px; min-height: 18px; }
  .mt { margin-top: 10px; }
  .obra { display: flex; gap: 14px; margin-top: 10px; font-weight: 700; }
  .obra .caja { flex: 0 0 200px; }
  table.lineas { width: 100%; border-collapse: collapse; margin-top: 8px; }
  table.lineas th { background: #1f5fa8; color: #fff; font-size: 9.5px; padding: 4px 6px; text-align: left; }
  table.lineas th.num, table.lineas td.num { text-align: right; }
  table.lineas td { padding: 3.5px 6px; vertical-align: top; }
  table.lineas tbody tr:nth-child(odd) td { background: #f2f2f2; }
  .pie { display: flex; gap: 20px; margin-top: 16px; page-break-inside: avoid; }
  .pago { width: 330px; flex-shrink: 0; }
  .pago .cuerpo { background: #f2f2f2; padding: 6px 8px; line-height: 1.5; }
  table.tot { flex: 1; border-collapse: collapse; height: fit-content; }
  table.tot th { background: #1f5fa8; color: #fff; font-size: 9.5px; padding: 4px 6px; }
  table.tot td { padding: 4px 8px; text-align: right; }
  table.tot tr.final td { font-weight: 700; border-top: 1px solid #999; }
  .banner { margin-top: 18px; page-break-inside: avoid; }
  .banner img { width: 100%; display: block; }
  @media print { .no-print { display: none; } }
  .no-print { position: fixed; top: 8px; right: 8px; background: #1f5fa8; color: #fff; border: 0; border-radius: 6px; padding: 8px 14px; font-weight: 700; cursor: pointer; }
</style></head><body>
  <button class="no-print" onclick="window.print()">Imprimir / Guardar PDF</button>
  <div class="cabecera"><img src="${LOGO_CABECERA}" alt="ALSO CASALS"></div>

  <div class="bloques">
    <div class="col-izq">
      <div class="titulo-azul">BORRADOR FACTURA</div>
      <div class="caja">BORRADOR OT${num}</div>
      <div class="titulo-azul mt">C.I.F CLIENTE</div>
      <div class="caja">${escapa(cifCliente || "")}</div>
    </div>
    <div class="col-fecha">
      <div class="titulo-azul">FECHA BORRADOR</div>
      <div class="caja">${fechaLarga(hoy)}</div>
    </div>
    <div class="col-cli">
      <div class="titulo-azul">INFORMACIÓN CLIENTE</div>
      <div class="caja" style="min-height:60px">${escapa(cliente || "")}</div>
    </div>
  </div>

  <div class="obra"><div class="caja">Nº Obra:&nbsp;&nbsp;OT ${num}</div></div>

  <table class="lineas">
    <thead><tr>
      <th style="width:110px">COD. ARTÍCULO</th>
      <th>DESCRIPCIÓN</th>
      <th class="num" style="width:64px">CANTIDAD</th>
      <th class="num" style="width:60px">PRECIO</th>
      <th class="num" style="width:40px">DTO</th>
      <th class="num" style="width:66px">IMPORTE</th>
      <th class="num" style="width:34px">IVA</th>
    </tr></thead>
    <tbody>
      ${filas.map(filaHtml).join("\n")}
    </tbody>
  </table>

  <div class="pie">
    <div class="pago">
      <div class="titulo-azul">FORMA DE PAGO</div>
      <div class="cuerpo">
        Recibo al cobro&nbsp;&nbsp;CAIXABANC<br>
        ES8621003502922200160922 &nbsp;<b>SWIFT:</b> CAIXESBBXXX<br>
        <b>Vtos.:</b> ${fechaLarga(vto)}<br>
        <b>Importes:</b> ${eurN(total)} €
      </div>
    </div>
    <table class="tot">
      <thead><tr><th>BASE IMPONIBLE</th><th>%</th><th>IVA</th><th>TOTAL</th></tr></thead>
      <tbody>
        <tr><td>${eurN(base)}</td><td>${IVA_PCT}</td><td>${eurN(iva)}</td><td></td></tr>
        <tr class="final"><td>${eurN(base)}</td><td></td><td></td><td>${eurN(total)}</td></tr>
      </tbody>
    </table>
  </div>

  <div class="banner"><img src="${BANNER_FERROSCA}" alt="ferrosCA"></div>
</body></html>`;

  return html;
}

function escapa(s) {
  return (s ?? "").toString().replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
